//! Manufacturer ("vendor") lookup from the first half of a MAC address.
//!
//! The list comes from the three public IEEE registries and is compiled into
//! the program (`data/oui.tsv`, ~1.7 MB, generated by `tools/make-oui.py`), so
//! it works offline on Linux and Windows alike:
//!
//! * **MA-L** — 6 hex digits (24-bit prefix), the classic "OUI" of big vendors;
//! * **MA-M** — 7 hex digits (28-bit), and **MA-S** — 9 hex digits (36-bit),
//!   small blocks used by many IoT, camera and smart-home makers. These sit
//!   inside MA-L blocks owned by the IEEE itself, so the *longest* matching
//!   prefix wins.
//!
//! Memory: the text stays in the binary's read-only data. The first lookup
//! builds three sorted indexes of `(prefix, &str)` pairs that point into that
//! text (about 1 MB, built once, never copied), and every lookup after that is
//! at most three binary searches.

use std::sync::OnceLock;

use super::mac::Mac;

/// `PREFIX<TAB>Vendor name` per line (prefix = 6, 7 or 9 hex digits).
static OUI_TSV: &str = include_str!("../../data/oui.tsv");

/// One sorted index per prefix length, longest first.
struct Index {
    /// (prefix length in hex digits, sorted entries)
    tables: [(usize, Vec<(u64, &'static str)>); 3],
}

/// The prefix → vendor index, built on first use.
static INDEX: OnceLock<Index> = OnceLock::new();

/// The index (built once from the embedded OUI list).
fn index() -> &'static Index {
    INDEX.get_or_init(|| {
        let mut tables = [(9, Vec::new()), (7, Vec::new()), (6, Vec::with_capacity(41_000))];
        for line in OUI_TSV.lines() {
            let Some((hex, name)) = line.split_once('\t') else { continue };
            let Ok(value) = u64::from_str_radix(hex, 16) else { continue };
            if let Some((_, t)) = tables.iter_mut().find(|(len, _)| *len == hex.len()) {
                t.push((value, name));
            }
        }
        // The generator already sorts, but sorting here keeps lookups correct
        // even if someone edits the file by hand.
        for (_, t) in &mut tables {
            t.sort_unstable_by_key(|e| e.0);
            t.shrink_to_fit();
        }
        Index { tables }
    })
}

/// The first `digits` hex digits of the MAC address as a number.
fn prefix(mac: &Mac, digits: usize) -> u64 {
    let all = mac.0.iter().fold(0u64, |acc, b| (acc << 8) | u64::from(*b)); // 12 hex digits
    all >> (4 * (12 - digits))
}

/// Return the manufacturer for `mac`, or a helpful note when there is none.
pub fn lookup(mac: &Mac) -> Option<&'static str> {
    if mac.is_randomized() {
        // Not in any registry: chosen at random by the device itself.
        return Some("Private (randomized) address");
    }
    index().tables.iter().find_map(|(digits, table)| {
        let key = prefix(mac, *digits);
        table.binary_search_by_key(&key, |e| e.0).ok().and_then(|i| table.get(i)).map(|e| e.1)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_vendor() {
        let pi = Mac([0xB8, 0x27, 0xEB, 1, 2, 3]);
        assert_eq!(lookup(&pi), Some("Raspberry Pi Foundation"));
    }

    #[test]
    fn prefix_math() {
        let m = Mac([0x12, 0x34, 0x56, 0x78, 0x9A, 0xBC]);
        assert_eq!(prefix(&m, 6), 0x123456);
        assert_eq!(prefix(&m, 7), 0x1234567);
        assert_eq!(prefix(&m, 9), 0x123456789);
    }

    #[test]
    fn longest_prefix_wins() {
        // Find any MA-S entry and check it beats its IEEE-owned MA-L parent.
        let (_, mas) = &index().tables[0];
        let (value, name) = mas[mas.len() / 2];
        let b = (value << 12).to_be_bytes(); // 36-bit prefix → 48-bit MAC
        let mac = Mac([b[2], b[3], b[4], b[5], b[6], b[7]]);
        if !mac.is_randomized() {
            assert_eq!(lookup(&mac), Some(name));
        }
    }

    #[test]
    fn randomized_and_sizes() {
        assert_eq!(lookup(&Mac([0xDA, 0, 0, 0, 0, 1])), Some("Private (randomized) address"));
        assert!(index().tables[2].1.len() > 30_000);
        assert!(index().tables[0].1.len() > 1_000);
    }
}
